/bin/bash -lc "node --input-type=module <<'JS'
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { join } from 'node:path';
const dir = await mkdtemp(join(process.cwd(), '.launch-check-'));
const child = spawn('npm', ['start'], { env: { ...process.env, PORT: '0', DB_PATH: join(dir, 'db.sqlite') }, detached: true, stdio: ['ignore', 'pipe', 'pipe'] });
try {
  let output = '';
  const port = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('Startup timed out')), 5000);
    child.stdout.on('data', chunk => {
      output += chunk;
      const match = output.match(/listening on port (\\d+)/);
      if (match) { clearTimeout(timer); resolve(match[1]); }
    });
    child.on('error', reject);
  });
  const response = await fetch("'`http://127.0.0.1:${port}/health`);
  if (response.status !== 200 || (await response.text()) !== '"'{\"status\":\"ok\"}') throw new Error('Health check failed');
  console.log('npm start: health check passed');
} finally {
  const exited = once(child, 'exit');
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(dir, { recursive: true, force: true });
}
JS
